contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        c.SetLogFile(address(this));

        c.Deposit{value: depositAmount}();
        uint bal = c.balances(address(this));
        uint minSum = c.MinSum();

        bool eligible = bal >= minSum && bal >= collectAmount;
        bool tooBig = collectAmount > bal;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint histAfter = LogFile(address(this)).History(0).Time == 0 ? 0 : uint(0);
        // The array is public; its length is not directly observable as a member.
        // Use the fact that a successful collect appends exactly one entry:
        // we detect growth by checking that the first entry exists (Time != 0)
        // and the entry's Val equals either depositAmount (from Deposit) or collectAmount (from Collect).
        // Simpler: read the last message via the public LastMsg getter? LastMsg is not public.
        // Public History(uint) getter requires an index; use index 0 as first message.

        // Since AddMessage is called on Deposit too, History(0) will be the deposit message.
        // A successful Collect appends a second message at index 1.
        bool secondExists = false;
        if (!tooBig || eligible) {
            // try to read index 1
            // The public getter for History(uint) returns (address,string,uint,uint)
            // If index out of bounds it reverts; we cannot catch view reverts easily in Solidity pre-0.8.20
            // So instead we test by checking the Val field of History(1) if it exists.
            // But we cannot know if it exists without calling.
            // Use a low-level staticcall instead? Not allowed per constraints (only c's public surface).
        }

        // Given constraints, use the contract's own storage via public History(uint) getter only at index 0
        // and infer that a collect adds a second entry by checking the return value of History(1) would revert.
        // To avoid reverts, we assert on the stored balance effect and event-like last message via History(0) Val.

        // Fallback rule: Collect succeeds exactly when eligible, and then stored balance decreases by collectAmount;
        // when not eligible, stored balance is unchanged.
        uint balAfter = c.balances(address(this));

        if (eligible) {
            assert(!reverted && balAfter == bal - collectAmount);
        } else {
            assert(reverted || balAfter == bal);
        }
    }
}

