        } catch {
            reverted = true;
        }

        uint afterBalance = c.balances(address(this));
        uint afterEth = address(c).balance;

        if (beforeBalance >= minSum) {
            if (!reverted) {
                assert(afterBalance == beforeBalance - collectAmount && afterEth == beforeEth - collectAmount);
            } else {
                assert(afterBalance == beforeBalance && afterEth == beforeEth);
            }
        } else {
            assert(afterBalance == beforeBalance && afterEth == beforeEth);
        }
    }

    receive() external payable {}
}

